  'Revision {document} {revision} training has been completed successfully. It is now Ready for Publishing; Document Control was told.': 'Đào tạo của phiên bản {document} {revision} đã hoàn tất. Phiên bản đã sẵn sàng để xuất bản; Kiểm soát tài liệu đã được thông báo.',
  'The lines of requirement {number} were saved. Send it for review when it is ready.': 'Đã lưu các dòng của yêu cầu {number}. Gửi rà soát khi đã sẵn sàng.',
  'Requirement {number} was approved. Its lines can now be opened as trainings.': 'Yêu cầu {number} đã được phê duyệt. Có thể mở đào tạo từ các dòng của yêu cầu.',
