  'The line of requirement {number} was signed by QA.': 'Dòng của yêu cầu {number} đã được QA ký.',
  'Requirement {number} went back to draft with your reason.': 'Yêu cầu {number} đã trở về bản nháp kèm lý do của bạn.',
  'The line moved from {from} to {to}. The old month and the reason stay on the line.': 'Dòng đã chuyển từ tháng {from} sang tháng {to}. Tháng cũ và lý do vẫn được giữ trên dòng.',
  'The line moves from {from} to {to}, the month right after the registered one (SOP.0003 5.3.6). It cannot be moved further or a second time.': 'Dòng sẽ chuyển từ tháng {from} sang tháng {to}, tháng ngay sau tháng đã đăng ký (SOP.0003 5.3.6). Không thể dời xa hơn hoặc dời lần thứ hai.',
  'This line was already moved to the month after the registered one. SOP.0003 allows only that one move.': 'Dòng này đã được dời sang tháng sau tháng đã đăng ký. SOP.0003 chỉ cho phép dời một lần đó.',
  'Training {number} was opened for {topic}, due at the end of {month}. Continue in Training Activities.': 'Đã mở đào tạo {number} cho {topic}, hạn hoàn thành cuối tháng {month}. Tiếp tục tại Hoạt động Đào tạo.',
