  "↑ 5% from last month": "↑ 5% so với tháng trước",
  "↑ 7% from last month": "↑ 7% so với tháng trước",
  "1. Scan QR with Google Authenticator, Microsoft Authenticator, or Authy.": "1. Quét mã QR bằng Google Authenticator, Microsoft Authenticator hoặc Authy.",
  "2. Enter the 6-digit code to complete setup.": "2. Nhập mã 6 chữ số để hoàn tất thiết lập.",
  "2FA Policy: Required": "Chính sách 2FA: Bắt buộc",
  "A copy is Returned when its scan is uploaded in Scans and filled files (choose the copy there); record it as Lost or Voided if the paper will not come back. Do this before the training is confirmed as completed; QA can still confirm, and the open copies are written in the Audit Trail.": "Bản sao được ghi là Đã trả khi bản quét của nó được tải lên trong Bản quét và tệp đã điền (chọn bản sao ở đó); ghi là Mất hoặc Đã huỷ nếu giấy không được trả lại. Làm việc này trước khi đào tạo được xác nhận hoàn thành; QA vẫn có thể xác nhận, và các bản sao đang mở sẽ được ghi vào Nhật ký kiểm toán.",
  "A link is not stored or fingerprinted. The page it points to can change after the content is approved.": "Liên kết không được lưu hoặc tính dấu vân tay. Trang mà nó trỏ tới có thể thay đổi sau khi nội dung được phê duyệt.",
  "A recipient needs at least one channel. Tick one, or remove the recipient.": "Người nhận cần ít nhất một kênh. Hãy chọn một kênh hoặc xoá người nhận.",
  "A second person checks each scan against the paper.": "Một người thứ hai kiểm tra từng bản quét với bản giấy.",
  "A template is kept as a Word file for others to start new documents from, so it never requires training and has no training period, planned date or completion date. Training applies to the documents created from it.": "Mẫu được giữ dưới dạng tệp Word để người khác tạo tài liệu mới từ đó, nên mẫu không bao giờ yêu cầu đào tạo và không có thời gian đào tạo, ngày dự kiến hay ngày hoàn thành. Đào tạo áp dụng cho các tài liệu được tạo từ mẫu.",
  "A test restore puts the backup into a scratch database, runs the checks and drops the database; production is not changed.": "Khôi phục thử đưa bản sao lưu vào một cơ sở dữ liệu tạm, chạy các kiểm tra rồi xoá cơ sở dữ liệu đó; dữ liệu production không bị thay đổi.",
  "A training review of this person is still open": "rà soát đào tạo của người này vẫn đang mở",
  "A visitor or a temporary contractor has no account: only the name and the organisation are written on the attendee list.": "Khách tham quan hoặc nhà thầu tạm thời không có tài khoản: chỉ tên và tổ chức được ghi trên danh sách tham dự.",
