  "Only completed backups whose integrity check passed are listed, newest first. Tick the one to restore.": "Chỉ hiện các bản sao lưu đã hoàn tất và vượt qua kiểm tra toàn vẹn, mới nhất trước. Chọn bản cần khôi phục.",
  "Only effective assessments are listed. Its content is written into the enabled form APD.0009 as the exam file and the answer key of this activity; the title of the assessment is not written in the form.": "Chỉ hiện các đánh giá hiệu lực. Nội dung của nó được ghi vào biểu mẫu APD.0009 đang bật dưới dạng tệp bài kiểm tra và đáp án của hoạt động này; tiêu đề đánh giá không được ghi vào biểu mẫu.",
