  "Create from a SOP pattern": "Tạo theo mẫu của SOP",
  "One Training Number covers all the sessions. Each session has its own topics, trainer, date, place, people, materials and test.": "Một mã đào tạo bao gồm tất cả các buổi. Mỗi buổi có chủ đề, giảng viên, ngày, nơi tổ chức, người tham gia, tài liệu và bài kiểm tra riêng.",
  "No session yet. Press Add session to add the first one.": "Chưa có buổi đào tạo nào. Bấm Thêm buổi đào tạo để thêm buổi đầu tiên.",
  "No session yet. Press Add session to add the first one: the people, the materials and the test all belong to a session.": "Chưa có buổi đào tạo nào. Bấm Thêm buổi đào tạo để thêm buổi đầu tiên: người tham gia, tài liệu và bài kiểm tra đều thuộc về một buổi.",
  "After the due date": "Sau hạn hoàn thành",
