  "Text style": "Kiểu chữ",
  "That is every record.": "Đó là toàn bộ bản ghi.",
  "The change this backup protects, for example CC-2026-0150.": "Thay đổi mà bản sao lưu này bảo vệ, ví dụ CC-2026-0150.",
  "The check did not finish": "Kiểm tra chưa hoàn tất",
  "The columns could not be loaded. Close this window and try again.": "Không tải được các cột. Hãy đóng cửa sổ này và thử lại.",
  "The copy is closed and does not change again. The reason stays in the Audit Trail.": "Bản sao đã đóng và không thay đổi nữa. Lý do được giữ trong Nhật ký kiểm toán.",
  "The figures on this page are sample data and the buttons do not run a backup or a restore. Nothing here is a record of your system.": "Các số liệu trên trang này là dữ liệu mẫu và các nút không chạy sao lưu hay khôi phục. Không có gì ở đây là bản ghi của hệ thống bạn.",
  "The file holds every record that matches the filters on the screen.": "Tệp chứa mọi bản ghi khớp với bộ lọc trên màn hình.",
  "The file stays on record, marked as removed with your reason.": "Tệp vẫn được lưu, được đánh dấu là đã xoá cùng lý do của bạn.",
  "The lines do not match the scan. The person who typed them types again; this one stays on record.": "Các dòng không khớp với bản quét. Người đã nhập sẽ nhập lại; bản này vẫn được lưu.",
  "The literal, fixed text this component inserts wherever it's used in a Document Name Format.": "Văn bản cố định mà component này chèn ở mọi nơi nó được dùng trong Định dạng tên tài liệu.",
  "The matrix requires nobody else for this topic.": "Ma trận không yêu cầu ai khác cho chủ đề này.",
  "The newest icons could not be loaded: the icons built into the application are shown.": "Không tải được biểu tượng mới nhất: đang hiển thị biểu tượng tích hợp trong ứng dụng.",
  "The person must hold the permission": "Người đó phải có quyền",
  "The preview is invalid. Confirmation is disabled until the policy is corrected.": "Bản xem trước không hợp lệ. Không thể xác nhận cho đến khi chính sách được sửa.",
  "The record is not deleted or changed: it stays in the list as voided with your reason and signature.": "Bản ghi không bị xoá hay thay đổi: nó vẫn trong danh sách ở trạng thái đã huỷ cùng lý do và chữ ký của bạn.",
  "The right answer": "Đáp án đúng",
  "The same list is shown on the in-app and on the email screen of this event.": "Danh sách giống nhau được hiển thị trong ứng dụng và trên màn hình email của sự kiện này.",
  "The session is complete.": "Buổi đào tạo đã hoàn tất.",
  "The system is processing the Controlled Copy information. Please wait a moment.": "Hệ thống đang xử lý thông tin bản sao kiểm soát. Vui lòng đợi trong giây lát.",
  "The temporary password is generated securely by the server after e-signature confirmation.": "Mật khẩu tạm được máy chủ tạo an toàn sau khi xác nhận chữ ký điện tử.",
  "The trainer, the date and the place can be changed until the training starts. People already notified must be told again.": "Có thể thay đổi giảng viên, ngày và địa điểm cho đến khi đào tạo bắt đầu. Những người đã được thông báo phải được báo lại.",
  "The user can only sign in from Start through End. Outside this window their account is automatically suspended.": "Người dùng chỉ có thể đăng nhập từ Bắt đầu đến Kết thúc. Ngoài khoảng này, tài khoản tự động bị đình chỉ.",
  "The user will be unable to log in while suspended. All data and records will be preserved.": "Người dùng sẽ không thể đăng nhập khi bị đình chỉ. Mọi dữ liệu và bản ghi vẫn được giữ nguyên.",
  "The user's account will be permanently deactivated. All historical records, documents, and audit trail entries will be preserved.": "Tài khoản người dùng sẽ bị vô hiệu hoá vĩnh viễn. Mọi hồ sơ lịch sử, tài liệu và mục nhật ký kiểm toán vẫn được giữ nguyên.",
  "Their authenticator and trusted devices are switched off.": "Ứng dụng xác thực và các thiết bị tin cậy của họ đã bị tắt.",
  "Theme color": "Màu chủ đề",
  "There is no placeholder to show.": "Không có placeholder để hiển thị.",
  "These credentials can be used to sign in to the system. The password is temporary and must be changed on the user's first login.": "Thông tin này có thể dùng để đăng nhập hệ thống. Mật khẩu là tạm thời và phải được đổi ở lần đăng nhập đầu tiên.",
  "They are signed out on every device.": "Họ bị đăng xuất trên mọi thiết bị.",
  "They are told by e-mail and set up multi-factor authentication again at the next sign-in.": "Họ được thông báo qua email và thiết lập lại xác thực đa yếu tố ở lần đăng nhập tiếp theo.",
  "This action cannot be undone.": "Không thể hoàn tác thao tác này.",
  "This actor type is not allowed for the selected action.": "Loại tác nhân này không được phép cho hành động đã chọn.",
  "This backup also holds a separate settings part, made before it was removed. It is not restored on its own: the settings are inside the database.": "Bản sao lưu này còn có phần cài đặt riêng được tạo trước khi bị gỡ. Phần này không được khôi phục riêng: cài đặt nằm trong cơ sở dữ liệu.",
  "This day is after the due date of the training.": "Ngày này sau ngày đến hạn của đào tạo.",
  "This dialog will automatically close when connection is restored": "Hộp thoại này sẽ tự đóng khi kết nối được khôi phục",
  "This file type cannot be previewed.": "Không thể xem trước loại tệp này.",
  "This filter is fixed for the current view.": "Bộ lọc này cố định cho chế độ xem hiện tại.",
  "This Form was filled in and signed by hand -- attach the executed scan": "Biểu mẫu này đã được điền và ký tay -- hãy đính kèm bản quét đã thực hiện",
  "This list shows configuration scope, not one universal effective policy. A document-type override applies only when its document type matches.": "Danh sách này hiển thị phạm vi cấu hình, không phải một chính sách hiệu lực chung. Ghi đè theo loại tài liệu chỉ áp dụng khi loại tài liệu khớp.",
  "This notification offers no placeholders.": "Thông báo này không có placeholder.",
  "This object has no action to configure.": "Đối tượng này không có hành động để cấu hình.",
  "This policy says": "Chính sách này quy định",
  "This recipient is already in the list.": "Người nhận này đã có trong danh sách.",
  "This revision": "Bản sửa đổi này",
  "This will remove your current authenticator app setup. You will need to re-enroll to use it for MFA. Your email OTP fallback will remain active.": "Thao tác này sẽ xoá thiết lập ứng dụng xác thực hiện tại. Bạn sẽ cần đăng ký lại để dùng cho MFA. Phương án OTP qua email dự phòng vẫn hoạt động.",
  "Time left": "Thời gian còn lại",
  "Timing and quiet hours hold back the email; a digest groups the emails of a person into one.": "Thời điểm và giờ yên tĩnh sẽ giữ email lại; bản tổng hợp gộp email của một người thành một.",
  "Title": "Tiêu đề",
