  "Training Planned Date": "Ngày dự kiến đào tạo",
  "Training Planned Date is the start of the training period (the day the document is approved), not the day the training is held; the period ends after the Training Period (Days). The Training Completion Date is the day the training was held.": "Ngày dự kiến đào tạo là ngày bắt đầu thời gian đào tạo (ngày tài liệu được phê duyệt), không phải ngày tổ chức đào tạo; thời gian kết thúc sau Thời gian đào tạo (ngày). Ngày hoàn thành đào tạo là ngày tổ chức đào tạo.",
  "Training Status": "Trạng thái đào tạo",
  "Covered by the training of": "Được đào tạo trong đợt của tài liệu",
  "This revision needs no training of its own: it was read in the training {number} of {document}, completed on the day shown, and was published with that document. For this reason its own Pending Training step is not part of its flow (SOP.0003: the need for training is decided for each document by the training impact assessment).": "Bản sửa đổi này không cần đào tạo riêng: nó đã được đọc trong đợt đào tạo {number} của {document}, hoàn tất vào ngày ghi bên trên, và được phát hành cùng tài liệu đó. Vì vậy bước Chờ đào tạo của riêng nó không nằm trong luồng của bản này (SOP.0003: nhu cầu đào tạo được quyết định cho từng tài liệu bằng đánh giá tác động đào tạo).",
  "Try adjusting your search": "Thử điều chỉnh tìm kiếm",
