  "A copy of this version is opened as a draft. This version stays effective until the new one is approved.": "Một bản sao của phiên bản này được mở dưới dạng bản nháp. Phiên bản này vẫn hiệu lực cho đến khi phiên bản mới được phê duyệt.",
  "A counter is made when the first Training Number of a department and year is issued.": "Bộ đếm được tạo khi số đào tạo đầu tiên của một bộ phận và năm được cấp.",
  "A dedicated bucket. The system enables Versioning and Object Lock Compliance.": "Một bucket riêng. Hệ thống bật Phiên bản và Tuân thủ khoá đối tượng.",
  "A draft for your department. The request number is issued by the system.": "Bản nháp cho bộ phận của bạn. Số yêu cầu do hệ thống cấp.",
  "A fixed part is written as it is. A typed part is filled in for each template and must follow its rule.": "Phần cố định được ghi nguyên như vậy. Phần nhập được điền cho từng mẫu và phải tuân theo quy tắc của nó.",
  "A large picture is reduced to a size that suits the report when it is inserted.": "Hình lớn được thu nhỏ về kích thước phù hợp với báo cáo khi được chèn.",
  "A manual copy counts toward the 3-2-1 rule only when the active Backup Policy declares it. Records can still be kept here.": "Bản sao thủ công chỉ được tính vào quy tắc 3-2-1 khi Chính sách sao lưu đang hoạt động khai báo. Bản ghi vẫn có thể được lưu ở đây.",
  "A matrix whose version waits for approval is left as it is; apply again once that version is decided.": "Ma trận có phiên bản đang chờ phê duyệt được giữ nguyên; hãy áp dụng lại sau khi phiên bản đó được quyết định.",
  "A matrix with a draft open gets the rows in that draft.": "Ma trận có bản nháp đang mở sẽ nhận các dòng trong bản nháp đó.",
  "A matrix with only an effective version gets a new draft; the head of the department approves it as usual.": "Ma trận chỉ có phiên bản hiệu lực sẽ nhận bản nháp mới; trưởng bộ phận phê duyệt như thường lệ.",
  "A new account must replace its temporary password at the first sign-in.": "Tài khoản mới phải đổi mật khẩu tạm ở lần đăng nhập đầu tiên.",
  "A new activity is created under the same number with the next letter. People who were absent or failed are listed.": "Một hoạt động mới được tạo dưới cùng số với chữ cái tiếp theo. Những người vắng mặt hoặc không đạt được liệt kê.",
  "A new template is named by the active Report Name Format. Nobody chooses a rule.": "Mẫu mới được đặt tên theo Định dạng tên báo cáo đang hoạt động. Không ai chọn quy tắc.",
  "A person a Head named: may share like the Head, but never excludes and never removes what a Head shared": "Người được Trưởng bộ phận chỉ định: có thể chia sẻ như Trưởng bộ phận, nhưng không bao giờ loại trừ và không bao giờ gỡ bỏ nội dung mà Trưởng bộ phận đã chia sẻ",
  "A person with several profiles gets the highest level.": "Người có nhiều hồ sơ sẽ nhận mức cao nhất.",
  "A presentation stamp is not an electronic signature.": "Dấu trình bày không phải chữ ký điện tử.",
  "A reference copy of the current Effective revision. It is watermarked, not tracked and never recalled after issue.": "Bản sao tham chiếu của bản sửa đổi hiệu lực hiện tại. Bản này có hình mờ, không được theo dõi và không bao giờ bị thu hồi sau khi phát hành.",
  "A restore is waiting to be finalized. No other restore can start until it is finalized or rolled back.": "Một lần khôi phục đang chờ hoàn tất. Không thể bắt đầu lần khôi phục khác cho đến khi lần này được hoàn tất hoặc hoàn tác.",
  "A scan that is stored cannot be deleted or replaced (the record store is locked). Check that it is the right file before you import.": "Bản quét đã lưu không thể bị xoá hoặc thay thế (kho bản ghi đã bị khoá). Hãy kiểm tra đúng tệp trước khi nhập.",
  "A scheduled report runs without anyone watching, so it needs at least one filter. It cannot be run with Full.": "Báo cáo theo lịch chạy mà không có người theo dõi, nên cần ít nhất một bộ lọc. Không thể chạy với chế độ Đầy đủ.",
  "A senior management position": "Một vị trí quản lý cấp cao",
  "A target chosen by the administrator, not the disk capacity.": "Mục tiêu do quản trị viên chọn, không phải dung lượng đĩa.",
  "A test done in the system, or a record written before the files were kept, has none.": "Bài kiểm tra làm trong hệ thống, hoặc bản ghi được tạo trước khi tệp được lưu, không có mục này.",
  "A trainee passes a test with at least this percentage. The system computes the result.": "Học viên đạt bài kiểm tra với ít nhất tỷ lệ phần trăm này. Hệ thống tự tính kết quả.",
  "A user sees the records where their name is in the flow; what more they see is chosen on their": "Người dùng thấy các bản ghi có tên mình trong luồng; phạm vi xem thêm được chọn trên",
