  "Closed by default: a user sees a document only when the Head of its Department or Business Unit shared it with them.": "Mặc định đóng: người dùng chỉ thấy tài liệu khi Trưởng bộ phận hoặc Trưởng đơn vị kinh doanh của tài liệu đã chia sẻ với họ.",
  "A user sees the Effective documents of every Department of their own Business Unit.": "Người dùng thấy tài liệu hiệu lực của mọi bộ phận trong đơn vị kinh doanh của mình.",
  "A user sees every Effective document of the system.": "Người dùng thấy mọi tài liệu hiệu lực của hệ thống.",
  "A user sees the Effective documents of their own Department.": "Người dùng thấy tài liệu hiệu lực của bộ phận mình.",
  "A user sees an Effective document only when the Head of its Department or Business Unit shared it with them (a folder or a document, right-click > Share), or when they are that Head. A Head can share with people, Positions, other Departments or everyone. The user still needs the Knowledge Base permission. This does not change Document Control.": "Người dùng chỉ thấy tài liệu hiệu lực khi Trưởng bộ phận hoặc Trưởng đơn vị kinh doanh của tài liệu đã chia sẻ với họ (thư mục hoặc tài liệu, chuột phải > Chia sẻ), hoặc khi chính họ là Trưởng bộ phận đó. Trưởng bộ phận có thể chia sẻ với người, Chức vụ, bộ phận khác hoặc mọi người. Người dùng vẫn cần quyền Cơ sở tri thức. Điều này không thay đổi Kiểm soát tài liệu.",
  "Everybody who may see a document already sees it, so there is no Share menu. Switch to Sharing when the Heads are ready to decide who sees what.": "Mọi người được phép xem tài liệu đều đã thấy tài liệu nên không có menu Chia sẻ. Chuyển sang Chia sẻ khi các Trưởng bộ phận sẵn sàng quyết định ai thấy gì.",
  "A user removed from a checked role keeps read-only visibility of the Document.": "Người dùng bị gỡ khỏi một vai trò được chọn vẫn giữ quyền xem chỉ đọc tài liệu.",
  "Only the": "Chỉ",
