  ". View All Documents in the Knowledge Base is a Knowledge Base permission of its own and changes nothing in Document Control.": ". Xem tất cả tài liệu trong Cơ sở tri thức là một quyền riêng của Cơ sở tri thức và không thay đổi gì trong Kiểm soát tài liệu.",
