  ", {count} repeated": ", {count} trang lặp lại",
  "{count} page(s) have no readable code or belong to no copy of this training (page {pages}). They were not stored: scan them again.": "{count} trang không có mã đọc được hoặc không thuộc bản sao nào của khóa đào tạo này (trang {pages}). Chúng không được lưu: hãy quét lại.",
  "{done} of {total} steps": "{done}/{total} bước",
  "All {count} steps are done. Well done!": "Đã hoàn thành tất cả {count} bước. Làm tốt lắm!",
