  "; more load as you scroll": "; tải thêm khi bạn cuộn",
  "{count} lines chosen": "Đã chọn {count} dòng",
  ". Choose people who miss the same training to add them to a training.": ". Hãy chọn những người cùng thiếu một khóa đào tạo để thêm vào khóa đó.",
  "Unlock": "Mở khoá",
  "Lock for QA": "Khoá cho QA",
  "Loading {role}s...": "Đang tải {role}...",
  "Showing {shown} of {total} records": "Hiển thị {shown}/{total} bản ghi",
