  "Type at least {count} characters: a document number, a name, a training number or a page.": "Nhập ít nhất {count} ký tự: số tài liệu, tên, số đào tạo hoặc một trang.",
  "{size} in {days} days": "{size} trong {days} ngày",
  "Training Matrices": "Ma trận Đào tạo",
  "{count} users hold both via combined profiles": "{count} người dùng giữ cả hai qua các hồ sơ kết hợp",
  "Uploading... {percent}%": "Đang tải lên... {percent}%",
  "No preview: {message}": "Không xem trước được: {message}",
