  "status.": "trạng thái.",
  "Training Planned Date:": "Ngày dự kiến đào tạo:",
  "Training Period End Date:": "Ngày kết thúc giai đoạn đào tạo:",
  ", the Valid Until date of the document.": ", ngày Hiệu lực đến của tài liệu.",
  "This document has no Valid Until date, so the Controlled Copy stays valid as long as the document does.": "Tài liệu này không có ngày Hiệu lực đến, nên Bản sao kiểm soát có hiệu lực chừng nào tài liệu còn hiệu lực.",
  "Distribution target:": "Đối tượng phân phối:",
  "Training Completion Date:": "Ngày hoàn thành đào tạo:",
  "· only layout for this template": "· bố cục duy nhất cho mẫu này",
  "Cover is page 1 of the final PDF; header and footer start from page 2. Leave \"To\" blank for \"to end\". Use Regenerate Preview at the top to apply changes.": "Bìa là trang 1 của PDF cuối; đầu trang và chân trang bắt đầu từ trang 2. Để trống \"Đến\" nghĩa là \"đến hết\". Dùng Tạo lại bản xem trước ở trên để áp dụng thay đổi.",
  "No cover: header and footer start from page 1. Leave \"To\" blank for \"to end\". Use Regenerate Preview at the top to apply changes. Enable Cover above to add one.": "Không có bìa: đầu trang và chân trang bắt đầu từ trang 1. Để trống \"Đến\" nghĩa là \"đến hết\". Dùng Tạo lại bản xem trước ở trên để áp dụng thay đổi. Bật Bìa ở trên để thêm.",
  "Name Parts ({count})": "Các phần tên ({count})",
  "Version v{version}. A template that already has a name keeps it when this format changes.": "Phiên bản v{version}. Mẫu đã có tên sẽ giữ nguyên tên khi định dạng này thay đổi.",
  "Only one format is active at a time; enabling another disables the one that was active. A template keeps the name it has when the active format changes. Manage the formats under": "Chỉ một định dạng hoạt động tại một thời điểm; bật định dạng khác sẽ tắt định dạng đang hoạt động. Mẫu giữ nguyên tên khi định dạng đang hoạt động thay đổi. Quản lý các định dạng tại",
  "A legal hold still blocks any removal. Holds are placed and released on each run's page; the files held now are listed under": "Lệnh giữ pháp lý vẫn chặn mọi việc xoá. Lệnh giữ được đặt và giải phóng trên trang của từng lần chạy; các tệp đang bị giữ được liệt kê tại",
  "Unsaved changes:": "Thay đổi chưa lưu:",
  "general information;": "thông tin chung;",
  "direct permissions;": "quyền trực tiếp;",
  "assignments;": "phân công;",
  "click": "bấm",
  "to review and confirm all changes with one electronic signature.": "để xem lại và xác nhận mọi thay đổi bằng một chữ ký điện tử.",
  "Created in": "Được tạo trong",
  "under a single electronic signature": "dưới một chữ ký điện tử duy nhất",
  "— if any step fails (e.g. a Segregation-of-Duties conflict), nothing is created": "— nếu bất kỳ bước nào thất bại (ví dụ xung đột Phân tách nhiệm vụ), không có gì được tạo",
  "State policies control who can": "Chính sách trạng thái kiểm soát ai có thể",
  "a revision at each lifecycle status — separate from workflow action policies which control transitions (submit/review/approve). System policies enforce strict participant visibility and can be deactivated but not deleted.": "một sửa đổi ở mỗi trạng thái vòng đời — tách biệt với chính sách hành động quy trình kiểm soát chuyển trạng thái (gửi/xem xét/phê duyệt). Chính sách hệ thống thực thi hiển thị nghiêm ngặt cho người tham gia và có thể bị tắt nhưng không thể xoá.",
  "Document Control only:": "Chỉ Kiểm soát tài liệu:",
  "these rules apply to revisions. Training, Reports and the other modules have no state capabilities — who can act there is set in Transition Policies and who sees records on the Access Profile.": "các quy tắc này áp dụng cho sửa đổi. Đào tạo, Báo cáo và các mô-đun khác không có năng lực trạng thái — ai được hành động được đặt trong Chính sách chuyển trạng thái, còn ai xem bản ghi được đặt trong Hồ sơ truy cập.",
