  "Retention of stored records: {from} → {to}": "Thời hạn lưu bản ghi: {from} → {to}",
  "Records stored from now on are locked until {date}. Nobody, administrators included, can shorten or delete them before then. Objects already stored keep the period they were written with. This cannot be undone.": "Các bản ghi lưu từ bây giờ bị khoá đến {date}. Không ai, kể cả quản trị viên, có thể rút ngắn hoặc xoá chúng trước thời điểm đó. Các đối tượng đã lưu giữ thời hạn được ghi khi tạo. Không thể hoàn tác.",
  "Shown in the top bar of the Dashboard on desktop, and stays there while the page is scrolled. Leave empty to use “{title}”.": "Hiển thị trên thanh trên cùng của Bảng điều khiển trên máy tính để bàn và giữ nguyên khi cuộn trang. Để trống để dùng “{title}”.",
