  "An external training needs no material of its own; add one if it helps.": "Khóa đào tạo bên ngoài không cần tài liệu riêng; thêm nếu hữu ích.",
  "A visitor is instructed by the department: no material is needed; add one if it helps.": "Khách được bộ phận hướng dẫn: không cần tài liệu; thêm nếu hữu ích.",
