  "This training is on {document}: the approved document is the material. Add slides or other material below if you want.": "Khóa đào tạo này dựa trên {document}: tài liệu đã phê duyệt chính là học liệu. Thêm slide hoặc tài liệu khác bên dưới nếu muốn.",
  "a document": "một tài liệu",
  "An external training has no test of its own; keep the certificate or the proof of attendance as evidence.": "Khóa đào tạo bên ngoài không có bài kiểm tra riêng; giữ chứng chỉ hoặc bằng chứng tham dự làm căn cứ.",
  "A visitor needs no test.": "Khách không cần bài kiểm tra.",
