  "No test or checklist is required: no session of this training is assessed by one (observation or reading confirmation).": "Không yêu cầu bài kiểm tra hay danh mục kiểm tra: không buổi nào của khóa này được đánh giá bằng một trong hai (quan sát hoặc xác nhận đã đọc).",
