  ": no Department Head is set in the master data. You confirm in place of the head, and the record says so.": ": chưa đặt Trưởng bộ phận trong dữ liệu gốc. Bạn xác nhận thay cho trưởng bộ phận và hồ sơ ghi lại điều đó.",
