  "Records of people who have left are kept {years} years after the day they left. A record whose retention has ended is only marked here; it is not deleted, and disposing of it follows a separate procedure with its own approval.": "Hồ sơ của người đã rời đi được lưu {years} năm sau ngày họ rời đi. Hồ sơ đã hết thời hạn lưu chỉ được đánh dấu ở đây; không bị xoá, và việc thanh lý tuân theo quy trình riêng có phê duyệt riêng.",
  "The assignment cannot be signed until they are done, or an exception is approved:": "Không thể ký phân công cho đến khi hoàn thành các mục này hoặc có ngoại lệ được phê duyệt:",
  "Training check: complete ({count} required).": "Kiểm tra đào tạo: hoàn tất ({count} yêu cầu).",
