  "Priority:": "Mức ưu tiên:",
  "{name} becomes the Active appearance: every new report is drawn with it. The appearance that is Active now becomes Inactive. Reports that are already made are not changed.": "{name} trở thành giao diện Đang hoạt động: mọi báo cáo mới sẽ được vẽ theo giao diện này. Giao diện đang hoạt động hiện tại sẽ chuyển thành Không hoạt động. Các báo cáo đã tạo không bị thay đổi.",
  "Report Name Format?": "Định dạng tên báo cáo?",
  "New report templates will have no name format and will be named by typing. Templates that already have a name keep it.": "Mẫu báo cáo mới sẽ không có định dạng tên và sẽ được đặt tên bằng cách nhập tay. Mẫu đã có tên sẽ giữ nguyên.",
  "Only one format is active at a time. This format will name every new report template, and the format that is active now will be deactivated. Templates that already have a name keep it.": "Chỉ một định dạng hoạt động tại một thời điểm. Định dạng này sẽ đặt tên cho mọi mẫu báo cáo mới, và định dạng đang hoạt động hiện tại sẽ bị tắt. Mẫu đã có tên sẽ giữ nguyên.",
  "Who may write, approve, upgrade or disable a report template, and who may run reports, is decided by permissions. Assign them to the Access Profiles that need them at": "Ai được viết, phê duyệt, nâng cấp hoặc tắt mẫu báo cáo và ai được chạy báo cáo do quyền quyết định. Hãy gán quyền cho các Hồ sơ truy cập cần chúng tại",
