  "Report Type?": "Loại báo cáo?",
  "disable": "tắt",
  "enable": "bật",
  "No new template or report can use this type. Reports already made are not affected; schedules of its templates are suspended.": "Không mẫu hay báo cáo mới nào có thể dùng loại này. Các báo cáo đã tạo không bị ảnh hưởng; lịch của các mẫu thuộc loại này bị tạm dừng.",
  "New templates and reports can use this type again.": "Mẫu và báo cáo mới có thể dùng lại loại này.",
  "Every notice sent about a scheduled report, including the ones skipped or failed. The most people one schedule can notify is set in": "Mọi thông báo gửi về một báo cáo theo lịch, kể cả những thông báo bị bỏ qua hoặc thất bại. Số người tối đa mà một lịch có thể thông báo được đặt trong",
