  "No Distribution Batches Found": "Không tìm thấy lô phân phối",
  "No Controlled Copies Found": "Không tìm thấy bản sao kiểm soát",
  "We couldn't find any distribution batches matching your filters. Try adjusting your search criteria.": "Không tìm thấy lô phân phối nào khớp bộ lọc. Hãy điều chỉnh tiêu chí tìm kiếm.",
  "We couldn't find any controlled copies matching your filters. Try adjusting your search criteria.": "Không tìm thấy bản sao kiểm soát nào khớp bộ lọc. Hãy điều chỉnh tiêu chí tìm kiếm.",
  "Controlled Copy Distribution Cancelled": "Đã huỷ phân phối bản sao kiểm soát",
  "Reissue Replacement Controlled Copy": "Cấp lại bản sao kiểm soát thay thế",
  "Distributed (cannot be cancelled)": "Đã phân phối (không thể huỷ)",
  "The published PDF could not be loaded from the server.": "Không thể tải tệp PDF đã xuất bản từ máy chủ.",
  "Request Controlled Copy is available only when the document is Active and the latest revision is Effective.": "Chỉ có thể yêu cầu Bản sao kiểm soát khi tài liệu đang Hiệu lực và phiên bản mới nhất đang Có hiệu lực.",
  "Edit Revision for Upgrade": "Chỉnh sửa phiên bản để nâng cấp",
  "Reason for Skipping Training": "Lý do bỏ qua đào tạo",
  "Periodic Review Cycle (Months) and Periodic Review Notification (Days) cannot be empty.": "Chu kỳ xem xét định kỳ (tháng) và Thông báo xem xét định kỳ (ngày) không được để trống.",
  "Review Date is required.": "Ngày xem xét là bắt buộc.",
  "Your changes have been saved.": "Các thay đổi của bạn đã được lưu.",
