  "Failed to create the Draft revision from the selected file.": "Không thể tạo phiên bản Nháp từ tệp đã chọn.",
  "Obsolete is only available when the document is Active, has a current Effective Revision, and has no revision in progress.": "Chỉ có thể đánh dấu Lỗi thời khi tài liệu đang Hiệu lực, có Phiên bản hiện hành Có hiệu lực và không có phiên bản nào đang thực hiện.",
  "The document has been marked as obsoleted.": "Tài liệu đã được đánh dấu là lỗi thời.",
  "The document could not be marked as obsoleted.": "Không thể đánh dấu tài liệu là lỗi thời.",
  "The document is back to the state it had before it was closed. Its revisions and controlled copies stay closed.": "Tài liệu đã trở về trạng thái trước khi bị đóng. Các phiên bản và bản sao kiểm soát của nó vẫn ở trạng thái đóng.",
  "The document could not be reopened.": "Không thể mở lại tài liệu.",
  "No revision available for publishing": "Không có phiên bản nào để xuất bản",
  "Failed to publish revision.": "Không thể xuất bản phiên bản.",
  "Document detail link has been copied to the clipboard.": "Đã sao chép liên kết chi tiết tài liệu vào bộ nhớ tạm.",
  "Unable to copy the document link.": "Không thể sao chép liên kết tài liệu.",
  "No effective published document available.": "Không có tài liệu đã xuất bản nào đang có hiệu lực.",
  "Refresh the page after access is granted, or contact Document Control if the issue persists.": "Hãy làm mới trang sau khi được cấp quyền, hoặc liên hệ Bộ phận Kiểm soát Tài liệu nếu vẫn còn lỗi.",
  "The official published PDF will appear here once the document has been published.": "Tệp PDF chính thức đã xuất bản sẽ xuất hiện ở đây sau khi tài liệu được xuất bản.",
  "Upload Anyway (Discard Unsaved Changes)": "Vẫn tải lên (bỏ các thay đổi chưa lưu)",
  "Edit Revision for Upgrade?": "Chỉnh sửa phiên bản để nâng cấp?",
  "A Draft upgrade revision is already in progress. These changes (Author, Co-Author, Reviewers, Approvers, Related/Correlated Documents, Periodic Review Cycle/Notification, Training) will be applied to that in-progress Draft. Nothing is saved until you explicitly click Save. Continue?": "Đang có một phiên bản nâng cấp Nháp. Các thay đổi này (Tác giả, Đồng tác giả, Người xem xét, Người phê duyệt, Tài liệu liên quan/tương quan, Chu kỳ/Thông báo xem xét định kỳ, Đào tạo) sẽ được áp dụng cho bản Nháp đang thực hiện đó. Không có gì được lưu cho đến khi bạn nhấn Lưu. Tiếp tục?",
  "You are about to configure the next revision (Author, Co-Author, Reviewers, Approvers, Related/Correlated Documents, Periodic Review Cycle/Notification, Training). Nothing is saved until you explicitly click Save. Continue?": "Bạn sắp cấu hình phiên bản tiếp theo (Tác giả, Đồng tác giả, Người xem xét, Người phê duyệt, Tài liệu liên quan/tương quan, Chu kỳ/Thông báo xem xét định kỳ, Đào tạo). Không có gì được lưu cho đến khi bạn nhấn Lưu. Tiếp tục?",
  "Status before it was closed": "Trạng thái trước khi bị đóng",
  "The review requirement changed after this revision was created. Re-open the revision to re-sync, then submit again.": "Yêu cầu xem xét đã thay đổi sau khi phiên bản này được tạo. Hãy mở lại phiên bản để đồng bộ lại, rồi gửi lại.",
  "Assign and save at least one Reviewer before continuing.": "Hãy chỉ định và lưu ít nhất một Người xem xét trước khi tiếp tục.",
  "Assign and save an Approver before continuing.": "Hãy chỉ định và lưu một Người phê duyệt trước khi tiếp tục.",
  "The document has been moved to Closed - Cancelled status.": "Tài liệu đã được chuyển sang trạng thái Đã đóng - Đã huỷ.",
  "Only a user with document workspace management permission can save Document Master metadata.": "Chỉ người dùng có quyền quản lý không gian làm việc tài liệu mới có thể lưu siêu dữ liệu Document Master.",
  "Enter a valid Document Number that is not already used before saving.": "Hãy nhập Số tài liệu hợp lệ và chưa được sử dụng trước khi lưu.",
  "Enter a valid Training Number that is not already used before saving.": "Hãy nhập Số đào tạo hợp lệ và chưa được sử dụng trước khi lưu.",
