  "Confirm Controlled Copy Destruction": "Xác nhận huỷ bản sao kiểm soát",
  "Essay (marked by hand)": "Tự luận (chấm tay)",
  "Every question needs at least 0.01 point.": "Mỗi câu hỏi cần ít nhất 0,01 điểm.",
  "Complete the assessment name and every question or line to see the preview.": "Hoàn tất tên bài đánh giá và từng câu hỏi hoặc dòng để xem bản xem trước.",
  "See the paper as it is printed": "Xem giấy như khi in",
  "Every question or line needs its text and its answers; a question needs points above zero.": "Mỗi câu hỏi hoặc dòng cần có nội dung và đáp án; câu hỏi cần điểm lớn hơn 0.",
  "Save the draft first.": "Hãy lưu bản nháp trước.",
  "A checklist has no score: each line is ticked Correct or Incorrect, and the person passes only when every line is as the key says.": "Danh mục kiểm tra không có điểm: mỗi dòng được đánh Đúng hoặc Sai, và người học chỉ đạt khi mọi dòng đúng như đáp án.",
  "Changing the Total Score shares it among the questions, in proportion to their points (see the tab Questions); changing the points of a question changes the total. An essay is marked by hand on the paper and the total score is typed in the Results step.": "Thay đổi Tổng điểm sẽ chia điểm cho các câu hỏi theo tỷ lệ điểm của chúng (xem tab Câu hỏi); thay đổi điểm của một câu sẽ thay đổi tổng. Bài tự luận được chấm tay trên giấy và tổng điểm được nhập ở bước Kết quả.",
  "The checklist in the enabled form APD.0009, as an activity gets it; the answer key is for the trainer only and is never handed out.": "Danh mục kiểm tra trong biểu mẫu APD.0009 đang bật, như một hoạt động nhận được; đáp án chỉ dành cho người đào tạo và không bao giờ được phát ra.",
  "The test in the enabled form APD.0009, as an activity gets it; the answer key is for the trainer only and is never handed out. The training topic is a sample line here; the name of each trainee, the Training Number and the date are written when it is printed for a session.": "Bài kiểm tra trong biểu mẫu APD.0009 đang bật, như một hoạt động nhận được; đáp án chỉ dành cho người đào tạo và không bao giờ được phát ra. Chủ đề đào tạo ở đây là dòng mẫu; tên từng học viên, Số đào tạo và ngày được ghi khi in cho một buổi.",
  "The assessment goes back to the designer, who can change it and send it again. The reason stays in the Audit Trail.": "Bài đánh giá được trả lại cho người thiết kế, người này có thể sửa và gửi lại. Lý do được lưu trong Nhật ký kiểm toán.",
  "Only a draft can be deleted. The reason stays in the Audit Trail.": "Chỉ có thể xoá bản nháp. Lý do được lưu trong Nhật ký kiểm toán.",
