  "Employee and Work Positions": "Nhân viên và Vị trí công việc",
  "Choose the employee and the Work Positions that are given. Each Work Position is checked against the matrix of its department.": "Chọn nhân viên và các Vị trí công việc được giao. Mỗi Vị trí công việc được đối chiếu với ma trận của bộ phận tương ứng.",
  "Besides the matrix of the Work Positions: move the SOPs, or type a Training Topic, that the person must have completed first. This step is optional.": "Ngoài ma trận của các Vị trí công việc: chuyển các SOP, hoặc nhập một Chủ đề đào tạo, mà người đó phải hoàn thành trước. Bước này không bắt buộc.",
  "Check what will be created. A draft is created; the matrix training of the person is checked again before it can be sent.": "Kiểm tra những gì sẽ được tạo. Một bản nháp được tạo; đào tạo theo ma trận của người đó được kiểm tra lại trước khi có thể gửi.",
  "Search by Work Position or department...": "Tìm theo Vị trí công việc hoặc bộ phận...",
  "Change: replaces a Work Position held": "Thay đổi: thay thế một Vị trí công việc đang giữ",
  "Change: added to the Work Positions held": "Thay đổi: thêm vào các Vị trí công việc đang giữ",
  "None: only the training that the matrix requires is checked": "Không: chỉ kiểm tra đào tạo mà ma trận yêu cầu",
  "We couldn't find any notifications matching your filters. Try adjusting your search criteria or clear filters.": "Không tìm thấy thông báo nào khớp bộ lọc. Hãy điều chỉnh tiêu chí tìm kiếm hoặc xoá bộ lọc.",
  "You're all caught up!": "Bạn đã xem hết thông báo!",
  "We couldn't find any personal notifications matching your filters.": "Không tìm thấy thông báo cá nhân nào khớp bộ lọc.",
