  "You approve this exact saved version. You must not be its author or the person who submitted it. Say what you checked.": "Bạn phê duyệt đúng phiên bản đã lưu này. Bạn không được là tác giả hoặc người đã gửi nó. Hãy nêu những gì bạn đã kiểm tra.",
