  "A logo is uploaded (remove it to type a text)": "Đã tải lên logo (xoá logo để nhập văn bản)",
  "The text of the header, for example the name of your company": "Văn bản của phần đầu, ví dụ tên công ty của bạn",
  "Code of the department (QA)": "Mã của bộ phận (QA)",
  "Next number, here three digits (001); the digits can be 1 to 8": "Số tiếp theo, ở đây ba chữ số (001); số chữ số có thể từ 1 đến 8",
  "Needs the number. The number starts again each year when the pattern has the year.": "Cần số. Số bắt đầu lại mỗi năm khi mẫu có năm.",
  "Needs the department: a department has one matrix. The number is optional.": "Cần bộ phận: mỗi bộ phận có một ma trận. Số không bắt buộc.",
  "Needs the number. An assessment belongs to no department.": "Cần số. Bài đánh giá không thuộc bộ phận nào.",
  "No material yet. A file (PDF, slides, video) or a link can be added in the planning step.": "Chưa có học liệu. Có thể thêm tệp (PDF, slide, video) hoặc liên kết ở bước lập kế hoạch.",
  "No material is needed for this training.": "Đào tạo này không cần học liệu.",
  "Cancel the training activity": "Huỷ hoạt động đào tạo",
  "The trainee may take the test once more. The reason stays in the Audit Trail.": "Học viên có thể làm bài kiểm tra thêm một lần. Lý do được lưu trong Nhật ký kiểm toán.",
  "The session cannot go ahead with this trainer unless another exception is approved.": "Buổi đào tạo không thể tiếp tục với người đào tạo này trừ khi một ngoại lệ khác được phê duyệt.",
  "Only before the attendee list is confirmed. The name and the reason stay in the Audit Trail. After that, mark the person absent instead.": "Chỉ trước khi danh sách người tham dự được xác nhận. Tên và lý do được lưu trong Nhật ký kiểm toán. Sau đó, hãy đánh dấu người đó vắng mặt.",
  "The person stays on the attendee list, as SOP.0003 5.3.4 requires. The reason is written on the row.": "Người đó vẫn nằm trong danh sách người tham dự, theo yêu cầu SOP.0003 5.3.4. Lý do được ghi trên dòng.",
  "The matrix must be updated": "Ma trận phải được cập nhật",
  "The effective matrix already covers the document": "Ma trận hiệu lực đã bao phủ tài liệu",
  "The department has no effective matrix yet.": "Bộ phận chưa có ma trận hiệu lực.",
  "Assess the Impact of the Document on the Training Matrix": "Đánh giá tác động của tài liệu đến ma trận đào tạo",
  "Impact on the matrix": "Tác động đến ma trận",
  "This version is a draft. Edit the matrix, save it, then submit it for approval with an electronic signature.": "Phiên bản này là bản nháp. Hãy sửa ma trận, lưu lại, rồi gửi phê duyệt bằng chữ ký điện tử.",
  "This version is waiting for the approver. It cannot be changed until it is approved or sent back.": "Phiên bản này đang chờ người phê duyệt. Không thể thay đổi cho đến khi được phê duyệt hoặc trả lại.",
  "This version is in use: it tells who must be trained on what. To change the matrix, upgrade the revision.": "Phiên bản này đang được sử dụng: nó cho biết ai phải được đào tạo những gì. Để thay đổi ma trận, hãy nâng cấp phiên bản.",
  "This version was replaced by a newer one and stays as history. It cannot be changed.": "Phiên bản này đã được thay bằng phiên bản mới hơn và được giữ làm lịch sử. Không thể thay đổi.",
  "Version sent back to draft": "Đã trả phiên bản về bản nháp",
  "List of participants in the Training": "Danh sách người tham gia đào tạo",
