  "The template stops at once: no report can be made from it and its schedules cannot run. Reports already made are kept. The change is recorded in the audit trail.": "Mẫu dừng ngay: không thể tạo báo cáo từ mẫu và các lịch của mẫu không thể chạy. Các báo cáo đã tạo vẫn được giữ. Thay đổi được ghi vào nhật ký kiểm toán.",
  "Failed to load workflow role catalog": "Không thể tải danh mục vai trò quy trình",
