  "Loading workflow authorization policies...": "Đang tải chính sách phân quyền quy trình...",
  "No policies match your filters. Try adjusting your search criteria.": "Không có chính sách nào khớp bộ lọc. Hãy điều chỉnh tiêu chí tìm kiếm.",
  "No policies found. Use 'New Policy' to create a custom policy, or check backend seed data.": "Không tìm thấy chính sách nào. Dùng 'Chính sách mới' để tạo chính sách tùy chỉnh, hoặc kiểm tra dữ liệu seed của backend.",
