  "Access is cumulative across all selected profiles -- there is no primary/secondary distinction.": "Quyền truy cập được cộng dồn từ tất cả hồ sơ đã chọn -- không có phân biệt chính/phụ.",
  "Unassigning a profile immediately removes every permission it grants once saved.": "Khi bỏ gán một hồ sơ, mọi quyền mà hồ sơ đó cấp sẽ bị gỡ ngay sau khi lưu.",
  "System profiles cannot be modified.": "Không thể sửa hồ sơ hệ thống.",
  "Inactive profiles cannot be changed here.": "Không thể thay đổi hồ sơ không hoạt động tại đây.",
  "Everything you may remove was taken away. The changes were recorded in the Audit Trail.": "Mọi thứ bạn có thể gỡ đã được gỡ. Các thay đổi đã được ghi vào Nhật ký kiểm toán.",
  "Which shares to show": "Chọn lượt chia sẻ để hiển thị",
  "You have not shared this item yourself.": "Bạn chưa tự chia sẻ mục này.",
  "Nobody except the Heads can see this yet.": "Chưa ai ngoài các Trưởng bộ phận có thể thấy mục này.",
  "Someone else changed this announcement. The list was reloaded.": "Người khác đã thay đổi thông báo này. Danh sách đã được tải lại.",
  "The announcement could not be deleted.": "Không thể xoá thông báo.",
  "Unable to load announcements": "Không thể tải thông báo",
  "Announcements shown to users after sign-in appear here. Try changing your search or filters.": "Các thông báo hiển thị cho người dùng sau khi đăng nhập sẽ xuất hiện ở đây. Hãy thử đổi tìm kiếm hoặc bộ lọc.",
  "Read it back, same bytes": "Đọc lại, các byte giống nhau",
  "Removed the test file": "Đã xoá tệp thử nghiệm",
  "Delete was refused (immutable)": "Việc xoá bị từ chối (bất biến)",
  "No. The Backup Agent holds only the public key. The private key is used only by the restore worker, and only for an approved restore.": "Không. Backup Agent chỉ giữ khóa công khai. Khóa riêng chỉ được trình phục hồi dùng, và chỉ cho một lần phục hồi đã được phê duyệt.",
  "Made by the server each time the file is opened, from the signed-in user and the server clock. The stored file is never modified, and the editors do not save it.": "Được máy chủ tạo mỗi lần mở tệp, từ người dùng đã đăng nhập và đồng hồ máy chủ. Tệp đã lưu không bao giờ bị sửa, và trình soạn thảo không lưu nó.",
  "Example values. The viewer is filled in when the file is opened.": "Giá trị ví dụ. Thông tin người xem được điền khi tệp được mở.",
  "Shown as an overlay on every page of the preview only. The stored PDF is never modified.": "Chỉ hiển thị dưới dạng lớp phủ trên mọi trang xem trước. Tệp PDF đã lưu không bao giờ bị sửa.",
  "Example values. The viewer is filled in at preview time.": "Giá trị ví dụ. Thông tin người xem được điền lúc xem trước.",
  "Unable to update department status.": "Không thể cập nhật trạng thái bộ phận.",
  "Unable to delete department.": "Không thể xoá bộ phận.",
  "Unable to update department.": "Không thể cập nhật bộ phận.",
  "Unable to create department.": "Không thể tạo bộ phận.",
  "Placed by hand on the preview. Choosing a corner puts it back there.": "Được đặt thủ công trên bản xem trước. Chọn một góc sẽ đưa nó về đó.",
  "Drag the code on the preview to place it anywhere on the page; drag a corner handle to resize it.": "Kéo mã trên bản xem trước để đặt ở bất kỳ đâu trên trang; kéo tay nắm ở góc để đổi kích thước.",
  "First page only: a whole copy can be matched from its first page, but loose pages scanned together cannot be sorted back into their copies.": "Chỉ trang đầu: có thể khớp cả bản sao từ trang đầu, nhưng các trang rời được quét cùng nhau không thể phân loại trở lại bản sao của chúng.",
  "Every page: each page carries its own code with its page number, so pages of many copies scanned as one file are sorted back into their copies and into order.": "Mọi trang: mỗi trang mang mã riêng kèm số trang, nên các trang của nhiều bản sao được quét thành một tệp sẽ được phân loại trở lại bản sao và đúng thứ tự.",
