  "No person with an Active account holds it. Switch off 'Only active accounts' to include the others.": "Không có người dùng có tài khoản Đang hoạt động nào giữ quyền này. Hãy tắt 'Chỉ tài khoản đang hoạt động' để gồm cả những người khác.",
  "The person may no longer share. What they shared stays until a Head removes it.": "Người này có thể không còn được chia sẻ. Nội dung đã chia sẻ vẫn còn cho đến khi Trưởng bộ phận gỡ.",
