  "As it stands now. The targets are also tested when the policy is activated.": "Như hiện tại. Các mục tiêu cũng được kiểm tra khi chính sách được kích hoạt.",
  "The result recorded when this version was activated.": "Kết quả được ghi khi phiên bản này được kích hoạt.",
  "Disaster Recovery Target Change": "Thay đổi mục tiêu phục hồi thảm hoạ",
  "Choose an active person": "Chọn một người đang hoạt động",
  "Disaster Declaration Authority Change": "Thay đổi thẩm quyền công bố thảm hoạ",
  "No manual offline copy is declared; at least 1 copy out of the server's reach is required": "Chưa khai báo bản sao ngoại tuyến thủ công; cần ít nhất 1 bản sao nằm ngoài tầm với của máy chủ",
  "Required: every backup contains the database, with everything stored in it: settings, users, audit trail, and the images, videos and large objects kept in database columns.": "Bắt buộc: mọi bản sao lưu đều chứa cơ sở dữ liệu, với mọi thứ lưu trong đó: cài đặt, người dùng, nhật ký kiểm toán, và hình ảnh, video và đối tượng lớn được giữ trong các cột cơ sở dữ liệu.",
  "Every stored version of every file in the three document buckets (documents, revisions, templates, controlled copies, executed records, reports, training files, and the pictures inside documents) is copied once, encrypted.": "Mọi phiên bản được lưu của mọi tệp trong ba nhóm tài liệu (tài liệu, phiên bản, mẫu, bản sao kiểm soát, hồ sơ đã thực hiện, báo cáo, tệp đào tạo và hình ảnh bên trong tài liệu) được sao chép một lần, có mã hoá.",
  "Unable to update sub-type.": "Không thể cập nhật loại con.",
  "Unable to create sub-type.": "Không thể tạo loại con.",
  "Unable to update sub-type status.": "Không thể cập nhật trạng thái loại con.",
