  "Every source field already has a component": "Mọi trường nguồn đã có thành phần",
  "Select a source field...": "Chọn một trường nguồn...",
  "UNCONTROLLED COPY — NOT VALID FOR PRODUCTION USE": "BẢN SAO KHÔNG KIỂM SOÁT — KHÔNG CÓ GIÁ TRỊ SỬ DỤNG SẢN XUẤT",
  "Uncontrolled Copies Policy updated.": "Đã cập nhật Chính sách Bản sao Không kiểm soát.",
  "Uncontrolled copies policy sections": "Các phần chính sách bản sao không kiểm soát",
  "Document Administration > Document Name Formats": "Quản trị Tài liệu > Định dạng tên tài liệu",
  "Training Administration > Training Code Rules": "Quản trị Đào tạo > Quy tắc mã đào tạo",
  "Report Administration > Report Name Formats": "Quản trị Báo cáo > Định dạng tên báo cáo",
  "Upload a template to see it filled with sample data.": "Tải lên một mẫu để xem mẫu được điền dữ liệu mẫu.",
  "Only a template written with tokens can be previewed. Download the starter file and upload a version written with tokens.": "Chỉ có thể xem trước mẫu được viết bằng token. Tải tệp khởi đầu và tải lên phiên bản được viết bằng token.",
  "This version does not agree with the form, so it cannot be previewed. Fix the problems in Check.": "Phiên bản này không khớp với biểu mẫu nên không thể xem trước. Hãy sửa các vấn đề trong Kiểm tra.",
  "Training vendor written as a draft": "Nhà cung cấp đào tạo đã được ghi thành bản nháp",
  "The vendor is Active again with the electronic signature of the person who activates it. The reason stays in the Audit Trail.": "Nhà cung cấp đã Hoạt động trở lại với chữ ký điện tử của người kích hoạt. Lý do được lưu trong Nhật ký kiểm toán.",
  "An external training with this unit gets a warning from now on. The reason stays in the Audit Trail.": "Đào tạo bên ngoài với đơn vị này sẽ nhận cảnh báo từ bây giờ. Lý do được lưu trong Nhật ký kiểm toán.",
