  "The file could not be read.": "Không thể đọc tệp.",
  "Download the blank form": "Tải biểu mẫu trống",
  "Its content was written into the form APD.0009 as the exam file and the answer key below (training topic from this activity). You can open them in the editor and change them; a later version of the assessment in the library does not change them. Remove takes both files off.": "Nội dung của nó đã được ghi vào biểu mẫu APD.0009 dưới dạng tệp bài kiểm tra và đáp án bên dưới (chủ đề đào tạo từ hoạt động này). Bạn có thể mở chúng trong trình soạn thảo và sửa; phiên bản đánh giá sau này trong thư viện không làm thay đổi chúng. Xoá sẽ gỡ cả hai tệp.",
  "Mark the right answers. After the content is reviewed and approved the questions cannot be changed.": "Đánh dấu đáp án đúng. Sau khi nội dung được duyệt và phê duyệt, không thể thay đổi câu hỏi.",
  "Open to Edit": "Mở để sửa",
