  "Time limit in minutes (leave empty for none)": "Giới hạn thời gian tính bằng phút (để trống nếu không có)",
  "Write it from the exam": "Viết từ bài kiểm tra",
  "Write the Test": "Viết bài kiểm tra",
  "This is a supplementary training: it keeps the material of the training it supplements, so nothing has to be added.": "Đây là khóa đào tạo bổ sung: khóa này giữ tài liệu của khóa được bổ sung nên không cần thêm gì.",
  "Required before the content is reviewed: a file or a link.": "Bắt buộc trước khi nội dung được xem xét: một tệp hoặc một liên kết.",
  "This is a supplementary training: it uses the test of the training it supplements.": "Đây là khóa đào tạo bổ sung: khóa này dùng bài kiểm tra của khóa được bổ sung.",
  "The test is written in the system (Test in the system), so no test file is needed; a file can still be added.": "Bài kiểm tra được viết trong hệ thống (Kiểm tra trong hệ thống) nên không cần tệp bài kiểm tra; vẫn có thể thêm tệp.",
  "Required before the content is reviewed: the {form} (APD.0009).": "Bắt buộc trước khi nội dung được xem xét: {form} (APD.0009).",
  "Press Save in the editor: the file becomes the": "Bấm Lưu trong trình soạn: tệp sẽ trở thành",
  "Training Materials are not required…": "Không yêu cầu Tài liệu đào tạo…",
  "An assessment form is not required…": "Không yêu cầu biểu mẫu đánh giá…",
