  "Write it from": "Viết từ",
  "Word or PDF, max 20 MB. Only organizers and reviewers see it.": "Word hoặc PDF, tối đa 20 MB. Chỉ người tổ chức và người xem xét thấy.",
  "Word or PDF, max 20 MB. It is printed for the employees.": "Word hoặc PDF, tối đa 20 MB. Được in cho nhân viên.",
  "The test was not saved": "Bài kiểm tra chưa được lưu",
  "The new appearance is created Inactive: activate it from the list when it is ready.": "Giao diện mới được tạo ở trạng thái Không hoạt động: hãy kích hoạt từ danh sách khi sẵn sàng.",
  "Making the preview file...": "Đang tạo tệp xem trước...",
  "Up to 100 scoped matches. Search to find more.": "Tối đa 100 kết quả trong phạm vi. Hãy tìm kiếm để xem thêm.",
  "Reason for the upgrade": "Lý do nâng cấp",
  "Create this appearance?": "Tạo giao diện này?",
  "Save Report Appearance?": "Lưu giao diện báo cáo?",
  "You are about to save changes to the report appearance.": "Bạn sắp lưu thay đổi cho giao diện báo cáo.",
  "It is the Active appearance, so every new report will be drawn with the change.": "Đây là giao diện Đang hoạt động, nên mọi báo cáo mới sẽ được vẽ với thay đổi này.",
  "An external training has no content or test of its own, so there is no review or approval of content. QA confirms the completion.": "Đào tạo bên ngoài không có nội dung hoặc bài kiểm tra riêng, nên không có rà soát hay phê duyệt nội dung. QA xác nhận hoàn thành.",
  "Only people the system found eligible for this step are listed.": "Chỉ liệt kê những người hệ thống thấy đủ điều kiện cho bước này.",
  "No eligible person was found. A person needs the permission of the step in this department and cannot be the person who prepared the activity.": "Không tìm thấy người đủ điều kiện. Người đó cần có quyền của bước này trong bộ phận và không thể là người lập hoạt động.",
  "The person who prepares the training chooses who reviews and approves the content. Only a person who holds the permission for the step, in the right department, and who is not the person who prepared it, can be chosen. The person chosen signs with an electronic signature.": "Người lập đào tạo chọn người rà soát và phê duyệt nội dung. Chỉ người có quyền của bước, đúng bộ phận và không phải người lập mới được chọn. Người được chọn ký bằng chữ ký điện tử.",
