  "When there are more groups than the number shown, the others are added together as one \"Other\" bar that says how many groups it holds.": "Khi có nhiều nhóm hơn số lượng hiển thị, các nhóm còn lại được gộp thành một cột \"Khác\" cho biết có bao nhiêu nhóm.",
  "Remove chart": "Xoá biểu đồ",
  "Can use this template": "Có thể dùng mẫu này",
  "Report metadata scope is independent of source-document access. An Access Profile without a scope has no access to this template. Scopes of the profiles a person holds are combined; the broadest applicable scope wins. Entire system includes metadata outside the user's department, but never file content.": "Phạm vi siêu dữ liệu báo cáo độc lập với quyền truy cập tài liệu nguồn. Hồ sơ truy cập không có phạm vi sẽ không truy cập được mẫu này. Phạm vi của các hồ sơ người dùng đang có được cộng dồn; phạm vi rộng nhất áp dụng sẽ thắng. Toàn hệ thống bao gồm siêu dữ liệu ngoài bộ phận của người dùng, nhưng không bao giờ gồm nội dung tệp.",
  "These Access Profiles are not active any more. Remove their scope before the template is saved.": "Các Hồ sơ truy cập này không còn hoạt động. Hãy gỡ phạm vi của chúng trước khi lưu mẫu.",
  "No access profiles": "Không có hồ sơ truy cập",
  "Loading template configuration…": "Đang tải cấu hình mẫu…",
  "Revision {revision} is effective and cannot be edited. To change this template, upgrade it: the new revision is written and approved while {revision} stays in use, then {revision} becomes Obsoleted.": "Phiên bản {revision} đang có hiệu lực và không thể sửa. Để thay đổi mẫu này, hãy nâng cấp: phiên bản mới được viết và phê duyệt trong khi {revision} vẫn đang được dùng, sau đó {revision} trở thành Lỗi thời.",
  "Assigned automatically when saved": "Tự động gán khi lưu",
  "0.0.1 when saved": "0.0.1 khi lưu",
  "A template for GMP decisions cannot be deleted; disable it instead. Every template, whatever its use, runs only after it is approved.": "Mẫu dùng cho quyết định GMP không thể xoá; hãy tắt mẫu thay vì xoá. Mọi mẫu, dù dùng cho mục đích gì, chỉ chạy sau khi được phê duyệt.",
  "Report files are kept permanently and never expire by age. Template changes never delete historical report files or audit records.": "Tệp báo cáo được giữ vĩnh viễn và không hết hạn theo thời gian. Thay đổi mẫu không bao giờ xoá tệp báo cáo lịch sử hoặc bản ghi kiểm toán.",
  "Allow Shown": "Cho phép các mục đang hiện",
  "Remove Shown": "Gỡ các mục đang hiện",
  "{allowed} of {total} fields allowed. Default columns: {defaultCount} of {max} (a report carries at most {max}).": "Đã cho phép {allowed}/{total} trường. Cột mặc định: {defaultCount}/{max} (một báo cáo có tối đa {max} cột).",
  "Drawing the pages…": "Đang vẽ các trang…",
  "Opening the report…": "Đang mở báo cáo…",
  "Sample data": "Dữ liệu mẫu",
  "Untitled chart": "Biểu đồ chưa có tiêu đề",
