  "No Records Found": "Không tìm thấy bản ghi",
  "Continue to Output": "Tiếp tục đến Đầu ra",
  "The report is made from your current access and is listed in Report Run History when it is ready.": "Báo cáo được tạo từ quyền truy cập hiện tại của bạn và được liệt kê trong Lịch sử chạy báo cáo khi sẵn sàng.",
  "It is signed electronically when you generate it; you give the reason in the signature window.": "Báo cáo được ký điện tử khi bạn tạo; bạn nêu lý do trong cửa sổ chữ ký.",
  "Cannot Create Report": "Không thể tạo báo cáo",
  "Preview: {name}": "Xem trước: {name}",
  "Unable to update document component.": "Không thể cập nhật thành phần tài liệu.",
  "Unable to create document component.": "Không thể tạo thành phần tài liệu.",
  "The person creating the Document types the number.": "Người tạo tài liệu tự nhập số.",
  "The system generates the number when the Document is first saved.": "Hệ thống sinh số khi tài liệu được lưu lần đầu.",
  "A system-defined component cannot be deleted": "Không thể xoá thành phần do hệ thống định nghĩa",
  "This component is used by a hierarchy": "Thành phần này đang được một cây phân cấp sử dụng",
  "The email message is saved. The change is recorded in the Audit Trail.": "Thư điện tử đã được lưu. Thay đổi được ghi vào Nhật ký kiểm toán.",
  "The email message could not be saved.": "Không thể lưu thư điện tử.",
  "The in-app notification design could not be loaded.": "Không thể tải thiết kế thông báo trong ứng dụng.",
  "The in-app notification design could not be saved.": "Không thể lưu thiết kế thông báo trong ứng dụng.",
  "The system issues the number when Requires Training is saved.": "Hệ thống cấp số khi Yêu cầu đào tạo được lưu.",
  "The evidence is filed: the training records of these persons are written.": "Bằng chứng đã được lưu: hồ sơ đào tạo của những người này đã được ghi.",
  "No evidence is filed for this training yet.": "Chưa có bằng chứng nào được lưu cho buổi đào tạo này.",
  "Another copy is numbered and recorded. Say why it is needed.": "Một bản sao khác được đánh số và ghi nhận. Hãy nêu lý do cần bản sao này.",
  "A pack was already printed for this session. The reason stays in the Audit Trail.": "Đã in một bộ cho buổi này. Lý do được lưu trong Nhật ký kiểm toán.",
  "The test of the session is uploaded as a file or written in the system (tab Assessment).": "Bài kiểm tra của buổi được tải lên dưới dạng tệp hoặc viết trong hệ thống (tab Đánh giá).",
  "The checklist form of the session is uploaded (tab Assessment).": "Biểu mẫu danh mục kiểm tra của buổi được tải lên (tab Đánh giá).",
  "Typed. Waiting for a second person to check it": "Đã nhập. Đang chờ người thứ hai kiểm tra",
  "Verify the Typed Results Against the Scan": "Đối chiếu kết quả đã nhập với bản quét",
  "The training is finished and QA was told, with the list APD.0108 of every department.": "Đào tạo đã kết thúc và QA đã được thông báo, kèm danh sách APD.0108 của từng bộ phận.",
  "Every head of department confirmed. The trainer can now finish the training (button Finish Training at the top): QA is told, with the list APD.0108 of every department.": "Mọi trưởng bộ phận đã xác nhận. Người đào tạo có thể kết thúc đào tạo (nút Kết thúc đào tạo ở trên): QA sẽ được thông báo, kèm danh sách APD.0108 của từng bộ phận.",
  "Search a SOP, or type a Training Topic...": "Tìm một SOP, hoặc nhập một Chủ đề đào tạo...",
  "No trainings selected: only the training that the matrix requires for the Work Position is checked.": "Chưa chọn đào tạo nào: chỉ đào tạo mà ma trận yêu cầu cho Vị trí công việc được kiểm tra.",
  "A person who is no longer in the system cannot be chosen and gets no record.": "Người không còn trong hệ thống không thể được chọn và không có hồ sơ.",
  "Legacy Training Evidence Filed": "Đã lưu bằng chứng đào tạo cũ",
