  "Keep Editing": "Tiếp tục chỉnh sửa",
  "Workflow eligibility determines which workflow steps users assigned this Access Profile can participate in. The catalog and allowed actions are configured in Workflow Authorization. Roles exist for Document Control and Training Management; the actions of the other modules (such as Reports and Security Review) follow permissions alone, which are set on the Permissions tab. Changes are applied when you click": "Điều kiện quy trình quyết định người dùng được gán Hồ sơ truy cập này có thể tham gia bước nào. Danh mục và hành động được phép được cấu hình trong Phân quyền quy trình. Vai trò tồn tại cho Kiểm soát Tài liệu và Quản lý Đào tạo; hành động của các mô-đun khác (như Báo cáo và Xem xét Bảo mật) chỉ theo quyền, được đặt trong tab Quyền. Thay đổi được áp dụng khi bạn nhấn",
  "Confirm Save": "Xác nhận lưu",
