  "Record sending": "Ghi nhận gửi",
  "{count} scans are of copies issued for reading only (Read and comply). They are not recalled by scan and no Record is made from them. Remove them here; the other scans are processed as usual. If such a copy has to be recalled, do it from Controlled Copies.": "{count} bản quét thuộc các bản sao chỉ dùng để đọc (Đọc và tuân thủ). Chúng không được thu hồi bằng quét và không tạo bản ghi. Hãy gỡ chúng ở đây; các bản quét khác được xử lý như bình thường. Nếu cần thu hồi bản sao đó, hãy làm từ màn hình Bản sao kiểm soát.",
  "A link lets a signed-in user who holds the Knowledge permission see a folder or a document of the Knowledge Base until it expires or is revoked. The Heads and the people they named make links in the Share dialog of the Knowledge explorer. Here you see every link and, if you hold the permission to manage object access rules, revoke one at once. The link itself is never shown again after it was made.": "Liên kết cho phép người dùng đã đăng nhập có quyền Tri thức xem một thư mục hoặc tài liệu của Cơ sở tri thức cho đến khi hết hạn hoặc bị thu hồi. Các Trưởng bộ phận và những người họ chỉ định tạo liên kết trong hộp thoại Chia sẻ của Trình khám phá tri thức. Tại đây bạn thấy mọi liên kết và, nếu có quyền quản lý quy tắc truy cập đối tượng, có thể thu hồi ngay. Bản thân liên kết không bao giờ hiển thị lại sau khi được tạo.",
  "The number is typed as TRN/<department code>/<YY>-<NNN>. The screen warns at once when it is already used, and warns (without refusing) when the year is not the current one. It can be changed, with a reason, until the training opens. A training created without that screen (for example by upgrading a revision) still gets a number from the system, which can then be changed the same way.": "Số được nhập theo dạng TRN/<mã bộ phận>/<YY>-<NNN>. Màn hình cảnh báo ngay khi số đã được dùng, và cảnh báo (không từ chối) khi năm không phải năm hiện tại. Có thể sửa số kèm lý do cho đến khi đào tạo mở. Đào tạo được tạo không qua màn hình đó (ví dụ khi nâng cấp phiên bản) vẫn được hệ thống cấp số, và sau đó có thể sửa theo cùng cách.",
  "{count} scan is of copies issued for reading only (Read and comply). They are not recalled by scan and no Record is made from them. Remove them here; the other scans are processed as usual. If such a copy has to be recalled, do it from Controlled Copies.": "{count} bản quét thuộc bản sao chỉ dùng để đọc (Đọc và tuân thủ). Chúng không được thu hồi bằng quét và không tạo bản ghi. Hãy gỡ chúng ở đây; các bản quét khác được xử lý như bình thường. Nếu cần thu hồi bản sao đó, hãy làm từ màn hình Bản sao kiểm soát.",
  "Occupational safety and company policy": "An toàn lao động và chính sách công ty",
  "General principles of GMP": "Nguyên tắc chung của GMP",
  "Data integrity and aseptic technique": "Toàn vẹn dữ liệu và kỹ thuật vô trùng",
  "Trends of the errors found in audits, complaints, OOS investigations and CAPA": "Xu hướng lỗi phát hiện từ đánh giá, khiếu nại, điều tra OOS và CAPA",
  "Could not export audit record as PDF.": "Không thể xuất bản ghi kiểm toán dưới dạng PDF.",
  "Open your authenticator app and scan the code below.": "Mở ứng dụng xác thực và quét mã bên dưới.",
  "The list could not be loaded": "Không thể tải danh sách",
  "Backup runs per day for the last 30 days, by result": "Số lần sao lưu mỗi ngày trong 30 ngày qua, theo kết quả",
  "Click to select the scanned, signed form": "Nhấn để chọn biểu mẫu đã quét và ký",
  "Failed to load the batch review list.": "Không thể tải danh sách xem xét lô.",
  "The document is not available.": "Tài liệu không khả dụng.",
  "No records matching your search": "Không có bản ghi nào khớp tìm kiếm",
  "The people chosen here are kept with the import. A person who is no longer in the system cannot be chosen and gets no record.": "Những người được chọn ở đây được giữ cùng lần nhập. Người không còn trong hệ thống không thể được chọn và không có hồ sơ.",
  "Failed to complete approval action.": "Không thể hoàn tất thao tác phê duyệt.",
