  "Failed to complete review action.": "Không thể hoàn tất thao tác xem xét.",
  "We couldn't find any revision records matching your filters. Try adjusting your search criteria or clear filters.": "Không tìm thấy bản ghi phiên bản nào khớp bộ lọc. Hãy điều chỉnh tiêu chí tìm kiếm hoặc xoá bộ lọc.",
  "OnlyOffice editor script did not load correctly.": "Tập lệnh trình soạn thảo OnlyOffice không tải đúng.",
  "Its validity follows the document's Valid Until date.": "Thời hạn hiệu lực của nó theo ngày Có hiệu lực đến của tài liệu.",
  "Copy distributed. The recipient e-mail is being sent in the background.": "Đã phân phối bản sao. Thư điện tử cho người nhận đang được gửi ở chế độ nền.",
  "You do not have access to this section.": "Bạn không có quyền truy cập phần này.",
  "A revision the person left:": "Phiên bản người đó đã rời khỏi:",
  "Try adjusting your search.": "Hãy thử điều chỉnh tìm kiếm.",
