  "Your permissions or department do not allow this action.": "Quyền hoặc bộ phận của bạn không cho phép thao tác này.",
  "Someone else changed this training activity. Reload it and try again.": "Người khác đã thay đổi hoạt động đào tạo này. Hãy tải lại và thử lại.",
  "This action is not available in the current status of the activity (for example, the content is locked once the people have been told).": "Thao tác này không khả dụng ở trạng thái hiện tại của hoạt động (ví dụ nội dung bị khoá sau khi đã thông báo cho mọi người).",
  "This action is not available in the current status of the activity.": "Thao tác này không khả dụng ở trạng thái hiện tại của hoạt động.",
  "This person is not eligible for the step (permission, department or separation of duties).": "Người này không đủ điều kiện cho bước này (quyền, bộ phận hoặc phân tách nhiệm vụ).",
  "A person is already designated for this step. Use Reassign to change the person.": "Đã có người được chỉ định cho bước này. Dùng Chỉ định lại để đổi người.",
  "The same person cannot do both steps of this process.": "Cùng một người không thể thực hiện cả hai bước của quy trình này.",
  "An electronic signature is required.": "Cần có chữ ký điện tử.",
  "A reason is required.": "Cần có lý do.",
  "A paper pack can be printed after the participants are notified and until the training is submitted for confirmation.": "Chỉ có thể in bộ giấy sau khi đã thông báo cho người tham gia và cho đến khi đào tạo được gửi xác nhận.",
  "A paper pack can be printed only for a session that is planned or held.": "Chỉ có thể in bộ giấy cho buổi đã lên kế hoạch hoặc đã diễn ra.",
  "Set the session to Paper or Mixed first.": "Hãy đặt buổi sang Giấy hoặc Kết hợp trước.",
  "A paper pack holds at most 500 trainees. Split the session.": "Một bộ giấy chứa tối đa 500 học viên. Hãy tách buổi.",
  "Choose Electronic, Paper or Mixed.": "Chọn Điện tử, Giấy hoặc Kết hợp.",
  "Results can be typed from paper only while the training is in progress.": "Chỉ có thể nhập kết quả từ giấy khi đào tạo đang diễn ra.",
  "A transcription of this session is already waiting to be checked.": "Đã có bản nhập của buổi này đang chờ kiểm tra.",
  "This transcription has already been decided.": "Bản nhập này đã được quyết định.",
  "Check the lines: each person once, and only people of this session.": "Kiểm tra các dòng: mỗi người một lần và chỉ người của buổi này.",
  "Someone in the list already has attendance recorded. Leave that person out.": "Có người trong danh sách đã được ghi điểm danh. Hãy loại người đó ra.",
  "Attach the scan of the paper first (Training Materials, paper evidence) and choose it.": "Hãy đính kèm bản quét giấy trước (Tài liệu đào tạo, bằng chứng giấy) và chọn nó.",
  "More than one day has passed since the session. Say why the results are typed late.": "Đã hơn một ngày kể từ buổi đào tạo. Hãy nêu lý do nhập kết quả muộn.",
  "The request is incomplete. Close the form and open it again.": "Yêu cầu chưa đầy đủ. Hãy đóng biểu mẫu và mở lại.",
  "The code is not right or has changed. Ask the trainer for the code on the screen now.": "Mã không đúng hoặc đã thay đổi. Hãy hỏi người đào tạo mã đang hiện trên màn hình.",
  "The check-in is not open for this training.": "Điểm danh chưa mở cho buổi đào tạo này.",
