  "This person has already passed; the result is not recorded again.": "Người này đã đạt; kết quả không được ghi lại.",
  "There is no attendance to correct yet.": "Chưa có điểm danh để sửa.",
  "Choose a different attendance from the one recorded.": "Hãy chọn điểm danh khác với điểm danh đã ghi.",
  "This person already has a score, a test or a transcribed result, so the attendance cannot be corrected.": "Người này đã có điểm, bài kiểm tra hoặc kết quả nhập, nên không thể sửa điểm danh.",
  "Choose how the person takes part.": "Chọn cách người này tham gia.",
  "The participation and the reason are the same as before.": "Cách tham gia và lý do giống như trước.",
  "This person is the trainer of the session. The trainer is written in the content of the training, not in the list of the people who take part.": "Người này là người đào tạo của buổi. Người đào tạo được ghi trong nội dung đào tạo, không nằm trong danh sách người tham gia.",
  "This person is on the list of the session. Remove them from the list before they become the trainer.": "Người này đang trong danh sách của buổi. Hãy gỡ khỏi danh sách trước khi họ trở thành người đào tạo.",
  "How a person takes part does not apply to an external training or a self-reading.": "Cách tham gia không áp dụng cho đào tạo bên ngoài hoặc tự đọc.",
