  "Check the test: each question needs its text, at least two answers for a choice question, and the right answer marked.": "Kiểm tra bài kiểm tra: mỗi câu cần nội dung, ít nhất hai đáp án cho câu lựa chọn và đáp án đúng được đánh dấu.",
