  "This matrix or position is too large to show at once. Narrow it with the search.": "Ma trận hoặc vị trí này quá lớn để hiển thị cùng lúc. Hãy thu hẹp bằng tìm kiếm.",
  "Confirm the attendee list first.": "Hãy xác nhận danh sách người tham dự trước.",
  "The content must be reviewed first.": "Nội dung phải được xem xét trước.",
  "The content and the test must be reviewed and approved first.": "Nội dung và bài kiểm tra phải được xem xét và phê duyệt trước.",
  "Add the Training Materials first: a file or a link (a training on a document uses the document). If none is needed, say so with a reason in the Training Materials tab.": "Hãy thêm Tài liệu đào tạo trước: một tệp hoặc liên kết (đào tạo về tài liệu dùng chính tài liệu). Nếu không cần, hãy nêu lý do trong tab Tài liệu đào tạo.",
  "Add the test (APD.0009) in the Assessment tab first: a session is assessed by a test. If none is needed, say so with a reason.": "Hãy thêm bài kiểm tra (APD.0009) trong tab Đánh giá trước: buổi đào tạo được đánh giá bằng bài kiểm tra. Nếu không cần, hãy nêu lý do.",
  "Add the checklist form (APD.0009) in the Assessment tab first: a session is assessed by a checklist. If none is needed, say so with a reason.": "Hãy thêm biểu mẫu danh mục kiểm tra (APD.0009) trong tab Đánh giá trước: buổi đào tạo được đánh giá bằng danh mục. Nếu không cần, hãy nêu lý do.",
  "This suspension is already cleared.": "Việc tạm ngưng này đã được xoá.",
  "Choose the outcome of the assessment.": "Chọn kết quả của bài đánh giá.",
  "A position does not belong to the department.": "Một vị trí không thuộc bộ phận.",
  "No effective matrix of the department contains this document yet.": "Chưa có ma trận hiệu lực nào của bộ phận chứa tài liệu này.",
  "The title, the due date and the training unit cannot be changed once the activity is notified. Only the remarks can.": "Không thể thay đổi tiêu đề, ngày đến hạn và đơn vị đào tạo sau khi hoạt động đã được thông báo. Chỉ có thể sửa ghi chú.",
  "This is the only session left. Cancel the whole activity instead.": "Đây là buổi duy nhất còn lại. Hãy huỷ toàn bộ hoạt động thay vì huỷ buổi.",
  "This session has already been held. Its trainer, date and place can no longer be changed.": "Buổi này đã diễn ra. Không thể thay đổi người đào tạo, ngày và địa điểm.",
  "A trainer exception was asked for this session. Deal with it before changing the trainer.": "Đã có yêu cầu ngoại lệ người đào tạo cho buổi này. Hãy xử lý trước khi đổi người đào tạo.",
  "Add at least one session.": "Thêm ít nhất một buổi.",
  "Every session needs a trainer.": "Mỗi buổi cần có người đào tạo.",
  "Add at least one participant.": "Thêm ít nhất một người tham gia.",
  "Upload the scan of the written test of every person (or one scan of the whole session) before finishing the training.": "Hãy tải lên bản quét bài kiểm tra viết của từng người (hoặc một bản quét cho cả buổi) trước khi kết thúc đào tạo.",
  "Only the Department Head of a department (Settings, Departments) confirms the self-reading of the people of that department, and no person of your department is waiting.": "Chỉ Trưởng bộ phận (Cài đặt, Bộ phận) xác nhận tự đọc cho người của bộ phận đó, và không có người nào của bộ phận bạn đang chờ.",
  "This session has no person of that department.": "Buổi này không có người của bộ phận đó.",
  "This person cannot be added or cannot be chosen for this step.": "Người này không thể được thêm hoặc không thể được chọn cho bước này.",
  "Every participant must be marked as attended or absent.": "Mọi người tham gia phải được đánh dấu có mặt hoặc vắng.",
  "Every participant who attended needs a result.": "Mọi người đã tham dự cần có kết quả.",
  "Start the training first: in the workspace, Prepare, Next (with your signature).": "Hãy bắt đầu đào tạo trước: trong không gian làm việc, chọn Chuẩn bị, Tiếp theo (kèm chữ ký).",
  "The attendance list was already sent to QA.": "Danh sách điểm danh đã được gửi cho QA.",
  "The exam of this activity is a PDF file: only the PDF copies can be made.": "Bài kiểm tra của hoạt động này là tệp PDF: chỉ có thể tạo bản sao PDF.",
  "Give the assessment a title.": "Đặt tiêu đề cho bài đánh giá.",
  "Add at least one question or line.": "Thêm ít nhất một câu hỏi hoặc dòng.",
  "A question or line is not complete: it needs a text, at least two answers with the right one marked, and points above zero.": "Một câu hỏi hoặc dòng chưa hoàn chỉnh: cần nội dung, ít nhất hai đáp án với đáp án đúng được đánh dấu và điểm lớn hơn 0.",
  "The picture of a question must be a PNG or a JPEG of up to 1.5 MB, and only a question of a test has one.": "Ảnh của câu hỏi phải là PNG hoặc JPEG tối đa 1,5 MB, và chỉ câu hỏi của bài kiểm tra mới có ảnh.",
  "An assessment has at most 200 questions or lines.": "Một bài đánh giá có tối đa 200 câu hỏi hoặc dòng.",
  "Only a draft can be changed, submitted or deleted. Make a new version of an effective assessment.": "Chỉ có thể sửa, gửi hoặc xoá bản nháp. Hãy tạo phiên bản mới của bài đánh giá đang có hiệu lực.",
  "This assessment is not waiting for approval.": "Bài đánh giá này không chờ phê duyệt.",
  "Only an effective assessment can be used or given a new version.": "Chỉ bài đánh giá có hiệu lực mới được dùng hoặc tạo phiên bản mới.",
  "Someone else changed this draft. Reload it and try again.": "Người khác đã thay đổi bản nháp này. Hãy tải lại và thử lại.",
  "A new version of this assessment is already a draft.": "Đã có bản nháp phiên bản mới của bài đánh giá này.",
  "Choose an assessment.": "Chọn một bài đánh giá.",
  "No session of this activity is assessed in this way: a test needs a session assessed by a Test, a checklist one assessed by a Checklist.": "Không có buổi nào của hoạt động này được đánh giá theo cách đó: bài kiểm tra cần buổi được đánh giá bằng Bài kiểm tra, danh mục cần buổi được đánh giá bằng Danh mục.",
  "This activity has not chosen an assessment from the library.": "Hoạt động này chưa chọn bài đánh giá từ thư viện.",
  "Send the attendance list to QA first.": "Hãy gửi danh sách điểm danh cho QA trước.",
  "Finish the training first: the trainer signs once every result is in.": "Hãy kết thúc đào tạo trước: người đào tạo ký sau khi có đủ mọi kết quả.",
  "The training was already finished.": "Đào tạo đã được kết thúc.",
