  "This copy was already returned, lost or voided. It does not change again.": "Bản sao này đã được trả, báo mất hoặc vô hiệu. Không thay đổi nữa.",
  "The state of the copy is not valid.": "Trạng thái bản sao không hợp lệ.",
  "The scanned file has too many pages. Send it in parts.": "Tệp quét có quá nhiều trang. Hãy gửi thành nhiều phần.",
  "A self-reading has no attendance: the person signs the reading in the system.": "Tự đọc không có điểm danh: người học ký xác nhận đọc trong hệ thống.",
  "A self-reading is confirmed by the person's own electronic signature. The trainer records nothing for them: remind the person to sign.": "Tự đọc được xác nhận bằng chữ ký điện tử của chính người học. Người đào tạo không ghi gì: hãy nhắc người đó ký.",
  "This person has already signed, or has no account to remind.": "Người này đã ký hoặc không có tài khoản để nhắc.",
  "This person's account is not Active (left the company or suspended), so they cannot sign. Use Cannot Read to record them as absent.": "Tài khoản của người này không hoạt động (đã rời công ty hoặc bị tạm ngưng) nên không thể ký. Dùng Không thể đọc để ghi họ vắng.",
  "A person whose account is not Active (left the company or suspended) cannot be put on a supplementary training. They stay Absent on the list until the account is Active again.": "Người có tài khoản không hoạt động (đã rời công ty hoặc bị tạm ngưng) không thể được đưa vào đào tạo bổ sung. Họ vẫn Vắng trong danh sách cho đến khi tài khoản hoạt động lại.",
  "Only a person who has not signed a self-reading yet can be recorded as unable to read.": "Chỉ người chưa ký tự đọc mới có thể được ghi là không thể đọc.",
  "This person was reminded less than an hour ago.": "Người này đã được nhắc cách đây chưa đến một giờ.",
  "A copy is returned by uploading its scan; record it as Lost or Voided here.": "Bản sao được trả bằng cách tải lên bản quét; ghi Mất hoặc Vô hiệu tại đây.",
  "The template of the form (APD.0117 for the attendance list, APD.0011 for the matrix) is not enabled. Upload it and enable it in Training Properties (form templates).": "Mẫu biểu mẫu (APD.0117 cho danh sách điểm danh, APD.0011 cho ma trận) chưa được bật. Hãy tải lên và bật trong Thuộc tính đào tạo (mẫu biểu mẫu).",
  "The enabled template APD.0117 does not have the parts of the form (header, general information, topics, list, confirmations). Upload the right file.": "Mẫu APD.0117 đang bật không có đủ các phần của biểu mẫu (đầu trang, thông tin chung, chủ đề, danh sách, xác nhận). Hãy tải lên đúng tệp.",
