  "This person can no longer be changed: the attendee list is confirmed, or attendance was recorded. Mark the person absent instead.": "Không thể thay đổi người này nữa: danh sách người tham dự đã xác nhận hoặc đã ghi điểm danh. Hãy đánh dấu người đó vắng.",
