  "This training is on a new or revised document. On the day it is held, send the attendance list to QA (SOP.0003 5.3.6).": "Buổi đào tạo này thuộc tài liệu mới hoặc đã sửa đổi. Vào ngày diễn ra, hãy gửi danh sách điểm danh cho QA (SOP.0003 5.3.6).",
  "Send the attendance list to QA on {date}, the day of the training (SOP.0003 5.3.6).": "Gửi danh sách điểm danh cho QA vào {date}, ngày diễn ra đào tạo (SOP.0003 5.3.6).",
  "The attendance list was due to QA on {date} and has not been sent. Send it now; the delay is recorded.": "Danh sách điểm danh đã đến hạn gửi QA từ {date} nhưng chưa được gửi. Hãy gửi ngay; việc chậm trễ được ghi nhận.",
  "This training was done on paper before the system and was imported with its document. It has no session; the scan of the paper record and the persons who were trained are in Legacy Training Evidence.": "Buổi đào tạo này được thực hiện trên giấy trước khi có hệ thống và được nhập cùng tài liệu. Không có buổi nào; bản quét hồ sơ giấy và những người đã được đào tạo nằm trong Bằng chứng đào tạo cũ.",
  " {count} participant was proposed when the document was prepared; they are put on the list of the first session, and you confirm the list.": " {count} người đã được đề xuất khi tài liệu được chuẩn bị; họ được đưa vào danh sách của buổi đầu tiên và bạn xác nhận danh sách.",
