  "Failed to load policies.": "Không thể tải các chính sách.",
  "This policy is the only decision about who may do this action (the old checks in the service were removed). With it inactive nobody can do the action from this state, whatever their permissions.": "Chính sách này là quyết định duy nhất về ai được thực hiện hành động này (các kiểm tra cũ trong dịch vụ đã được bỏ). Khi chính sách không hoạt động, không ai có thể thực hiện hành động từ trạng thái này, bất kể quyền hạn.",
